import {bit,numbers,contains} from './search.ts';
import type {GroundedAction,GraphplanAction,TransformAction,ActionLevel,GraphPlanResult} from './types.ts';

interface ExtractFrame {kind:'extract';level:number;goals:bigint;stage:'start'|'return';key?:string}
interface AssignFrame {
  kind:'assign';level:number;goals:number[];stage:'start'|'choose'|'assigned'|'lower';
  next:number;chosen:GraphplanAction[];covered:bigint;
  choices?:GraphplanAction[];choice?:number;
}
type Frame = ExtractFrame | AssignFrame;


export class Mutexes {
  rows:bigint[];
  count:number;
  constructor(size:number) {
    this.rows = Array(size).fill(0n);
    this.count = 0;
  }

  add(first:number,second:number):void {
    this.rows[first] |= bit(second);
    this.rows[second] |= bit(first);
    this.count++;
  }

  has(first:number,second:number):boolean {
    return (this.rows[first] & bit(second)) !== 0n;
  }

  compatible(facts:bigint):boolean {
    for (const fact of numbers(facts)) if ((this.rows[fact] & facts) !== 0n) return false;
    return true;
  }
}

export function buildActionLevel(actions:TransformAction[],facts:bigint,mutexes:Mutexes,factCount:number):ActionLevel {
  const elements:GraphplanAction[] = [];
  for (const action of actions) {
    if (contains(facts, action.pre) && mutexes.compatible(action.pre)) elements.push({...action, index: elements.length});
  }
  const actionCount = elements.length;
  for (const fact of numbers(facts)) {
    elements.push({number: null, fact, pre: bit(fact), add: bit(fact), del: 0n, original: null, index: elements.length});
  }
  const exclusive = new Mutexes(elements.length);
  for (let first = 0; first < elements.length; first++) {
    const x = elements[first];
    for (let second = first + 1; second < elements.length; second++) {
      const y = elements[second];
      const interference = (x.del & (y.pre | y.add)) !== 0n || (y.del & (x.pre | x.add)) !== 0n;
      const competing = numbers(x.pre).some(fact => (mutexes.rows[fact] & y.pre) !== 0n);
      if (interference || competing) exclusive.add(first, second);
    }
  }
  const achievers:GraphplanAction[][] = Array.from({length: factCount},():GraphplanAction[]=>[]);
  let nextFacts = 0n;
  for (const element of elements) {
    nextFacts |= element.add;
    for (const fact of numbers(element.add)) {
      if (element.original === null) achievers[fact].unshift(element);
      else achievers[fact].push(element);
    }
  }
  const nextMutexes = new Mutexes(factCount);
  const present = numbers(nextFacts);
  for (let first = 0; first < present.length; first++) {
    const p = present[first];
    for (let second = first + 1; second < present.length; second++) {
      const q = present[second];
      if (achievers[p].every(x => achievers[q].every(y => x.index !== y.index && exclusive.has(x.index, y.index)))) {
        nextMutexes.add(p, q);
      }
    }
  }
  return {elements, actionCount, mutexes: exclusive, achievers, nextFacts, nextMutexes};
}

export class Extractor {
  levels:ActionLevel[];
  memo:Set<string>;
  searched:number;
  memoHits:number;
  tried:number;
  constructor(actionLevels:ActionLevel[]) {
    this.levels = actionLevels;
    this.memo = new Set<string>();
    this.searched = 0;
    this.memoHits = 0;
    this.tried = 0;
  }

  extract(level:number,goals:bigint):GroundedAction[][]|null {
    const stack:Frame[] = [{kind:'extract',level,goals,stage:'start'}];
    let returned:GroundedAction[][]|null = null;
    const finish = (result:GroundedAction[][]|null):void => {
      returned = result;
      stack.pop();
    };
    while (stack.length > 0) {
      const frame = stack.at(-1)!;
      if (frame.kind === 'extract') {
        if (frame.stage === 'start') {
          if (frame.level === 0) {
            finish([]);
            continue;
          }
          frame.key = `${frame.level}:${frame.goals}`;
          if (this.memo.has(frame.key!)) {
            this.memoHits++;
            finish(null);
            continue;
          }
          this.searched++;
          frame.stage = 'return';
          stack.push({kind: 'assign', level: frame.level, goals: numbers(frame.goals), next: 0,
            chosen: [], covered: 0n, stage: 'start'});
        } else {
          if (returned === null) this.memo.add(frame.key!);
          finish(returned);
        }
        continue;
      }
      if (frame.stage === 'start') {
        while (frame.next < frame.goals.length && (frame.covered & bit(frame.goals[frame.next])) !== 0n) frame.next++;
        if (frame.next === frame.goals.length) {
          let preconditions = 0n;
          for (const element of frame.chosen) preconditions |= element.pre;
          frame.stage = 'lower';
          stack.push({kind: 'extract', level: frame.level - 1, goals: preconditions, stage: 'start'});
        } else {
          frame.choices = this.levels[frame.level - 1].achievers[frame.goals[frame.next]];
          frame.choice = 0;
          frame.stage = 'choose';
        }
      } else if (frame.stage === 'choose') {
        let selected:GraphplanAction|null = null;
        const mutexes = this.levels[frame.level - 1].mutexes;
        while (frame.choice! < frame.choices!.length) {
          const candidate = frame.choices![frame.choice!];
          frame.choice = frame.choice! + 1;
          if (frame.chosen.every(element => !mutexes.has(candidate.index, element.index))) {
            selected = candidate;
            break;
          }
        }
        if (selected === null) finish(null);
        else {
          this.tried++;
          frame.stage = 'assigned';
          stack.push({kind: 'assign', level: frame.level, goals: frame.goals, next: frame.next + 1,
            chosen: frame.chosen.concat(selected), covered: frame.covered | selected.add, stage: 'start'});
        }
      } else if (frame.stage === 'assigned') {
        if (returned === null) frame.stage = 'choose';
        else finish(returned);
      } else {
        if (returned === null) finish(null);
        else {
          const layer = frame.chosen.filter(element => element.original !== null)
            .sort((a, b) => a.number! - b.number!).map(element => element.original!);
          finish(returned.concat([layer]));
        }
      }
    }
    return returned;
  }
}

export function solve(actions:TransformAction[],factCount:number,initial:bigint,goal:bigint,limit:number):GraphPlanResult {
  const actionLevels:ActionLevel[] = [];
  const extractor = new Extractor(actionLevels);
  const logs:string[] = [];
  let facts = initial;
  let mutexes = new Mutexes(factCount);
  let previousFactCount = -1;
  let previousMutexCount = -1;
  const finish = (result:string,layers:GroundedAction[][]|null = null):GraphPlanResult => ({result, layers, plan: layers === null ? null : layers.flat(), logs,
    expanded: extractor.searched, generated: extractor.tried, memoHits: extractor.memoHits});
  for (let level = 0; ; level++) {
    const count = numbers(facts).length;
    logs.push(`fact level ${level}: facts=${count} mutexes=${mutexes.count}`);
    let attempted = false;
    if (contains(facts, goal) && mutexes.compatible(goal)) {
      attempted = true;
      const beforeSearch = extractor.searched;
      const beforeHits = extractor.memoHits;
      const layers = extractor.extract(level, goal);
      logs.push(`extract level ${level}: ${layers === null ? 'fail' : 'success'} ` +
        `searched=${extractor.searched - beforeSearch} memo_hits=${extractor.memoHits - beforeHits}`);
      if (layers !== null) return finish('solved', layers);
    }
    if (!attempted && level >= 1 && count === previousFactCount && mutexes.count === previousMutexCount) return finish('unreachable');
    if (level === limit) return finish('level limit');
    const next = buildActionLevel(actions, facts, mutexes, factCount);
    actionLevels.push(next);
    logs.push(`action level ${level}: actions=${next.actionCount} noops=${count} mutexes=${next.mutexes.count}`);
    previousFactCount = count;
    previousMutexCount = mutexes.count;
    facts = next.nextFacts;
    mutexes = next.nextMutexes;
  }
}

import {notation} from './pddl_parser.ts';
import {mask} from './search.ts';
import type {
  Domain, Problem, Atom, Literal, CandidateGrounded, SchemaStats,
  GroundedFact, GroundedModel, GroundedAction, ProblemObject
} from './types.ts';

export function subtype(type:string,expected:string,parents:Map<string,string|null>):boolean {
  for (let current = type; current !== null; current = parents.get(current)!) if (current === expected) return true;
  return false;
}

export function classifyPredicates(domain:Domain):void {
  const fluent = new Set<string>();
  for (const action of domain.actions) for (const literal of action.effects) fluent.add(literal.atom.predicate);
  domain.fluent = fluent;
  domain.static = new Set(domain.predicates.filter(predicate => !fluent.has(predicate.name)).map(predicate => predicate.name));
}

export function substitute(atom:Atom,assignment:Map<string,string>):Atom {
  return {predicate: atom.predicate, terms: atom.terms.map(term => assignment.get(term)!)};
}

export function ground(domain:Domain,problem:Problem):GroundedModel {
  const objectsByType = new Map<string,ProblemObject[]>(domain.types.map(type =>
    [type, problem.objects.filter(object => subtype(object.type, type, domain.parents))]));
  const initialAtoms = new Set<string>(problem.init.map(notation));
  const registry = new Map<string,Atom>();
  const register = (atom:Atom):string => {
    const key = notation(atom);
    registry.set(key, atom);
    return key;
  };
  for (const atom of problem.init) register(atom);
  const candidates:CandidateGrounded[] = [];
  const schemas:SchemaStats[] = [];
  for (const source of domain.actions) {
    const choices = source.parameters.map(parameter => objectsByType.get(parameter.type)!);
    let assignments = 1;
    for (const choice of choices) assignments *= choice.length;
    const counts = {source, assignments, candidates: 0, reachable: 0};
    schemas.push(counts);
    const assigned:string[] = [];
    function enumerate(index:number):void {
      if (index < choices.length) {
        for (const object of choices[index]) {
          assigned.push(object.name);
          enumerate(index + 1);
          assigned.pop();
        }
        return;
      }
      const assignment = new Map<string,string>(source.parameters.map((parameter, number) => [parameter.name, assigned[number]]));
      const conditions = source.conditions.map(literal => ({negative: literal.negative, atom: substitute(literal.atom, assignment)}));
      for (const literal of conditions) {
        const atom = literal.atom;
        if (atom.predicate !== '=' && !domain.static.has(atom.predicate)) continue;
        const truth = atom.predicate === '=' ? atom.terms[0] === atom.terms[1] : initialAtoms.has(notation(atom));
        if (truth === literal.negative) return;
      }
      const pre = new Set<string>();
      const neg = new Set<string>();
      for (const literal of conditions) {
        if (domain.fluent.has(literal.atom.predicate)) (literal.negative ? neg : pre).add(register(literal.atom));
      }
      const add = new Set<string>(source.adds.map(atom => register(substitute(atom, assignment))));
      const del = new Set<string>(source.deletes.map(atom => register(substitute(atom, assignment))));
      for (const key of add) del.delete(key);
      candidates.push({source, arguments: assigned.slice(), cost: source.cost, pre, neg, add, del, counts, reachable: false});
      counts.candidates++;
    }
    enumerate(0);
  }
  const reachable = new Set<string>(problem.init.filter(atom => domain.fluent.has(atom.predicate)).map(notation));
  let changed = true;
  while (changed) {
    changed = false;
    for (const candidate of candidates) {
      if (candidate.reachable || ![...candidate.pre].every(key => reachable.has(key))) continue;
      candidate.reachable = true;
      candidate.counts.reachable++;
      for (const key of candidate.add) reachable.add(key);
      changed = true;
    }
  }
  const facts = [...reachable].map(key => ({...registry.get(key)!, notation: key}));
  facts.sort((a, b) => {
    const predicate = domain.predicateTable.get(a.predicate)!.number - domain.predicateTable.get(b.predicate)!.number;
    if (predicate !== 0) return predicate;
    for (let index = 0; index < a.terms.length; index++) {
      const difference = problem.objectNumbers.get(a.terms[index])! - problem.objectNumbers.get(b.terms[index])!;
      if (difference !== 0) return difference;
    }
    return 0;
  });
  const factNumbers = new Map<string,number>(facts.map((fact, number) => [fact.notation, number]));
  const actions:GroundedAction[] = [];
  for (const candidate of candidates) {
    if (!candidate.reachable) continue;
    const factIds = (keys:Set<string>):number[] => [...keys].filter(key => factNumbers.has(key))
      .map(key => factNumbers.get(key)!).sort((a,b)=>a-b);
    const preFacts=factIds(candidate.pre), negFacts=factIds(candidate.neg);
    const addFacts=factIds(candidate.add), delFacts=factIds(candidate.del);
    const action:GroundedAction = {number:actions.length,name:candidate.source.name,source:candidate.source,
      arguments:candidate.arguments,cost:candidate.cost,
      notation:notation({predicate:candidate.source.name,terms:candidate.arguments}),
      preFacts,negFacts,addFacts,delFacts,
      pre:mask(preFacts),neg:mask(negFacts),add:mask(addFacts),del:mask(delFacts)};
    actions.push(action);
  }
  const initialFacts = problem.init.filter(atom => domain.fluent.has(atom.predicate)).map(atom => factNumbers.get(notation(atom))!);
  const goals = new Set<number>();
  const unreachable:Atom[] = [];
  for (const atom of problem.goals) {
    const key = notation(atom);
    if (factNumbers.has(key)) goals.add(factNumbers.get(key)!);
    else if (!domain.static.has(atom.predicate) || !initialAtoms.has(key)) unreachable.push(atom);
  }
  const goalFacts = [...goals].sort((a, b) => a - b);
  return {facts, factNumbers, actions, schemas, candidateCount: candidates.length, objectsByType, unreachable,
    initial: mask(initialFacts), goal: mask(goalFacts), goalFacts,
    staticCount: problem.init.filter(atom => domain.static.has(atom.predicate)).length,
    actionTable: new Map(actions.map(action => [action.notation, action]))};
}

import {bit,numbers,contains,applicable} from './search.ts';
import type {
  GroundedModel,GroundedAction,HeuristicRecord,HeuristicRelaxation,
  HeuristicLevels,Landmarks
} from './types.ts';
export const names = ['goalcount', 'hmax', 'hadd', 'ff', 'lmcount'];

function aggregate(values:number[],mode:string):number {
  let result = 0;
  for (const value of values) {
    if (value === Infinity) return Infinity;
    result = mode === 'max' ? Math.max(result, value) : result + value;
  }
  return result;
}

export class Engine {
  problem:GroundedModel;
  achievers:GroundedAction[][];
  cache:Map<bigint,HeuristicRecord>;
  constructor(problem:GroundedModel) {
    this.problem = problem;
    this.achievers = Array.from({length: problem.facts.length}, ():GroundedAction[] => []);
    for (const action of problem.actions) for (const fact of action.addFacts) this.achievers[fact].push(action);
    this.cache = new Map<bigint,HeuristicRecord>();
  }

  record(state:bigint):HeuristicRecord {
    if (!this.cache.has(state)) this.cache.set(state, {});
    return this.cache.get(state)!;
  }

  costs(state:bigint,mode:'max'|'sum'):number[] {
    const record = this.record(state);
    const key: 'cmax'|'cadd' = mode === 'max' ? 'cmax' : 'cadd';
    if (record[key] !== undefined) return record[key];
    const costs = this.problem.facts.map((_, fact) => (state & bit(fact)) !== 0n ? 0 : Infinity);
    let changed = true;
    while (changed) {
      changed = false;
      for (const action of this.problem.actions) {
        const value = action.cost + aggregate(action.preFacts.map(fact => costs[fact]), mode);
        for (const fact of action.addFacts) {
          if (value < costs[fact]) {
            costs[fact] = value;
            changed = true;
          }
        }
      }
    }
    record[key] = costs;
    return costs;
  }

  relaxedPlan(state:bigint):HeuristicRelaxation {
    const record = this.record(state);
    if (record.relaxed !== undefined) return record.relaxed;
    const costs = this.costs(state, 'sum');
    if (this.problem.goalFacts.some(fact => costs[fact] === Infinity)) {
      record.relaxed = {value: Infinity, plan: [], helpful: []};
      return record.relaxed;
    }
    const best = this.problem.facts.map((_, fact) => {
      let chosen: GroundedAction | null = null;
      let minimum = Infinity;
      for (const action of this.achievers[fact]) {
        const value = action.cost + aggregate(action.preFacts.map(pre => costs[pre]), 'sum');
        if (value < minimum) {
          chosen = action;
          minimum = value;
        }
      }
      return chosen;
    });
    const selected = new Set<number>();
    const pending = this.problem.goalFacts.filter(fact => (state & bit(fact)) === 0n);
    while (pending.length > 0) {
      const action = best[pending.pop()!]!;
      if (selected.has(action.number)) continue;
      selected.add(action.number);
      for (const fact of action.preFacts) if ((state & bit(fact)) === 0n) pending.push(fact);
    }
    const plan = [...selected].sort((a, b) => a - b).map(number => this.problem.actions[number]);
    let value = 0;
    for (const action of plan) value += action.cost;
    record.relaxed = {value, plan, helpful: plan.filter(action => applicable(state, action))};
    return record.relaxed;
  }

  levels(state:bigint):HeuristicLevels {
    const facts = this.problem.facts.map((_, fact) => (state & bit(fact)) !== 0n ? 0 : Infinity);
    const actions = this.problem.actions.map(() => Infinity);
    for (let level = 0; ; level++) {
      let changed = false;
      for (const action of this.problem.actions) {
        if (actions[action.number] !== Infinity || !action.preFacts.every(fact => facts[fact] <= level)) continue;
        actions[action.number] = level;
        for (const fact of action.addFacts) if (facts[fact] === Infinity) {
          facts[fact] = level + 1;
          changed = true;
        }
      }
      if (!changed) break;
    }
    return {facts, actions};
  }

  landmarks(state:bigint):Landmarks {
    const record = this.record(state);
    if (record.landmarks !== undefined) return record.landmarks;
    const levels = this.levels(state);
    if (this.problem.goalFacts.some(fact => levels.facts[fact] === Infinity)) {
      record.landmarks = {value: Infinity, facts: []};
      return record.landmarks;
    }
    const landmarks = new Set<number>(this.problem.goalFacts.filter(fact => (state & bit(fact)) === 0n));
    const verified = new Map<number,boolean>();
    const verify = (fact:number):boolean => {
      if (verified.has(fact)) return verified.get(fact)!;
      let reachable = state;
      let previous;
      do {
        previous = reachable;
        for (const action of this.problem.actions) {
          if ((action.add & bit(fact)) === 0n && contains(reachable, action.pre)) reachable |= action.add;
        }
      } while (reachable !== previous);
      const passes = !contains(reachable, this.problem.goal);
      verified.set(fact, passes);
      return passes;
    };
    for (const fact of landmarks) {
      const achievers = this.achievers[fact].filter(action => levels.actions[action.number] === levels.facts[fact] - 1);
      let common = achievers[0].pre;
      for (const action of achievers.slice(1)) common &= action.pre;
      for (const candidate of numbers(common & ~state)) {
        if (!landmarks.has(candidate) && verify(candidate)) landmarks.add(candidate);
      }
    }
    record.landmarks = {value: landmarks.size, facts: [...landmarks].sort((a, b) => a - b)};
    return record.landmarks;
  }

  value(state:bigint,name:string):number {
    if (name === 'none') return 0;
    const record = this.record(state);
    const key = name as 'goalcount'|'hmax'|'hadd'|'ff'|'lmcount';
    if (record[key] !== undefined) return record[key]!;
    let value:number;
    if (name === 'goalcount') value = this.problem.goalFacts.filter(fact => (state & bit(fact)) === 0n).length;
    else if (name === 'hmax') value = aggregate(this.problem.goalFacts.map(fact => this.costs(state, 'max')[fact]), 'max');
    else if (name === 'hadd') value = aggregate(this.problem.goalFacts.map(fact => this.costs(state, 'sum')[fact]), 'sum');
    else if (name === 'ff') value = this.relaxedPlan(state).value;
    else value = this.landmarks(state).value;
    record[key] = value;
    return value;
  }

  all(state:bigint):Record<string,number> {
    return Object.fromEntries(names.map(name => [name, this.value(state, name)]));
  }
}

import {mkdirSync,writeFileSync} from 'node:fs';
import * as parser from './pddl_parser.ts';
import * as grounding from './grounding.ts';
import * as heuristics from './heuristics.ts';
import * as search from './search.ts';
import * as graphplan from './graphplan.ts';
import type {
  Domain,Problem,Settings,SearchConfig,CandidatePlan,Step,
  GroundedModel,GroundedAction,TransformResult,TransformAction,
  PlanResult,GraphPlanResult,Validation,PlanAnalysis,Atom
} from './types.ts';

function append(lines:string[],values:string[]):void {
  for (const value of values) lines.push(value);
}

function list(heading:string,values:(string|number)[]):string {
  return `${heading} ${values.length === 0 ? '-' : values.join(' ')}`;
}

function numberList(values:number[]):string {
  return values.length === 0 ? '-' : values.join(',');
}

function valueText(value:number):string {
  return value === Infinity ? 'inf' : String(value);
}

function planCost(plan:GroundedAction[]):number {
  let cost = 0;
  for (const action of plan) cost += action!.cost;
  return cost;
}

function stepOf(action:GroundedAction):Step {
  return {name: action.name, arguments: action.arguments};
}

function stepText(step:Step):string {
  return parser.notation({predicate: step.name, terms: step.arguments});
}

function meaningfulLines(text:string):string[] {
  return text.slice(0, -1).split('\n').filter(line => line !== '' && !line.startsWith('#'));
}

function readSettings(text:string):Settings {
  const settings:Settings = {runs:[],repair:{algorithm:'',heuristic:'',tag:''},budget:0,weight:1,graphplan:0};
  for (const line of meaningfulLines(text)) {
    const [kind, first, second] = line.split(' ');
    if (kind === 'run' || kind === 'repair') {
      const configuration:SearchConfig = {algorithm:first,heuristic:second,tag:`${first} ${second}`};
      if (kind === 'run') settings.runs.push(configuration);
      else settings.repair = configuration;
    } else settings[kind] = Number(first);
  }
  return settings;
}

function readCandidates(text:string):CandidatePlan[] {
  const candidates:CandidatePlan[] = [];
  let current:CandidatePlan|null = null;
  for (const line of meaningfulLines(text)) {
    if (line.startsWith('plan ')) {
      const [, problem, label] = line.split(' ');
      current = {number: candidates.length + 1, problem, label, steps: []};
    } else if (line === 'end') candidates.push(current!);
    else {
      const [name, ...args] = line.slice(1, -1).split(' ');
      current!.steps.push({name, arguments: args});
    }
  }
  return candidates;
}

function argumentError(domain:Domain,arguments_:string[],expected:string[],table:Map<string,string>,noun:string):string|null {
  if (arguments_.length !== expected.length) return `expected ${expected.length} arguments, got ${arguments_.length}`;
  for (let index = 0; index < arguments_.length; index++) {
    const name = arguments_[index];
    if (!table.has(name)) return `unknown ${noun} ${name}`;
    if (!grounding.subtype(table.get(name)!, expected[index], domain.parents)) {
      return `argument ${index + 1} (${name}) is not of type ${expected[index]}`;
    }
  }
  return null;
}

function validateDomain(domain:Domain):void {
  const kept:Domain['actions'] = [];
  const diagnostics:string[] = [];
  for (const action of domain.actions) {
    let error = null;
    for (const parameter of action.parameters) {
      if (!domain.parents.has(parameter.type)) {
        error = `unknown type ${parameter.type}`;
        break;
      }
    }
    const parameters = new Map<string,string>(action.parameters.map(parameter => [parameter.name, parameter.type]));
    if (error === null) {
      for (const literal of action.conditions.concat(action.effects)) {
        const atom = literal.atom;
        if (atom.predicate !== '=' && !domain.predicateTable.has(atom.predicate)) error = `unknown predicate ${atom.predicate}`;
        else {
          const expected = atom.predicate === '=' ? ['object', 'object'] : domain.predicateTable.get(atom.predicate)!.types;
          error = argumentError(domain, atom.terms, expected, parameters, 'variable');
        }
        if (error !== null) {
          error = `${parser.notation(atom)}: ${error}`;
          break;
        }
      }
    }
    if (error !== null) diagnostics.push(`error: action ${action.name}: ${error}`);
    else kept.push(action);
  }
  domain.actions = kept;
  const used = new Set<string>();
  for (const action of kept) for (const literal of action.conditions.concat(action.effects)) used.add(literal.atom.predicate);
  for (const predicate of domain.predicates) {
    if (!used.has(predicate.name)) diagnostics.push(`warning: predicate ${predicate.name} is not used by any action`);
  }
  domain.diagnostics = diagnostics;
  domain.actionTable = new Map(kept.map(action => [action.name, action]));
  grounding.classifyPredicates(domain);
}

function validateProblem(domain:Domain,problem:Problem):void {
  problem.diagnostics = [];
  for (const [field, side] of [['init', 'init'], ['goals', 'goal']] as ['init'|'goals',string][]) {
    const kept:Atom[] = [];
    const seen = new Set<string>();
    for (const atom of problem[field]) {
      let error = null;
      if (!domain.predicateTable.has(atom.predicate)) error = `unknown predicate ${atom.predicate}`;
      else error = argumentError(domain, atom.terms, domain.predicateTable.get(atom.predicate).types, problem.objectTypes, 'object');
      const notation = parser.notation(atom);
      if (error === null && seen.has(notation)) error = 'duplicate';
      if (error !== null) problem.diagnostics.push(`warning: ${side} ${notation}: ${error}`);
      else {
        seen.add(notation);
        kept.push(atom);
      }
    }
    problem[field] = kept;
  }
}

function domainLines(domain:Domain):string[] {
  const lines = [`== domain ${domain.name} ==`];
  append(lines, domain.diagnostics);
  for (const type of domain.types) {
    const chain:string[] = [];
    for (let current:string|null = type; current !== null; current = domain.parents.get(current)!) chain.push(current);
    lines.push(`type ${chain.join(' < ')}`);
  }
  for (const predicate of domain.predicates) {
    lines.push(`predicate ${predicate.name}/${predicate.types.length} ${domain.fluent.has(predicate.name) ? 'fluent' : 'static'}`);
  }
  for (const action of domain.actions) {
    lines.push(`action ${action.name}/${action.parameters.length} cost=${action.cost} pre=${action.conditions.length} ` +
      `add=${action.adds.length} del=${action.deletes.length}`);
  }
  return lines;
}

function groundingLines(domain:Domain,problem:Problem):string[] {
  const model = problem.model;
  const lines = [`== problem ${problem.name} ==`];
  append(lines, problem.diagnostics);
  lines.push(`objects: ${problem.objects.length}`);
  for (const type of domain.types) lines.push(list(`  ${type}:`, model.objectsByType.get(type)!.map(object => object.name)));
  lines.push(`static facts: ${model.staticCount}`);
  for (const schema of model.schemas) {
    lines.push(`schema ${schema.source.name}: assignments=${schema.assignments} candidates=${schema.candidates} reachable=${schema.reachable}`);
  }
  lines.push(`candidates: ${model.candidateCount} reachable: ${model.actions.length}`);
  lines.push(`facts: ${model.facts.length} init: ${search.numbers(model.initial).length} goals: ${model.goalFacts.length}`);
  for (const atom of model.unreachable) lines.push(`unreachable goal: ${parser.notation(atom)}`);
  lines.push(list('facts by predicate:', domain.predicates.filter(predicate => domain.fluent.has(predicate.name))
    .map(predicate => `${predicate.name}=${model.facts.filter(fact => fact.predicate === predicate.name).length}`)));
  lines.push('facts:');
  for (let number = 0; number < model.facts.length; number++) lines.push(`  ${number} ${model.facts[number].notation}`);
  lines.push('actions:');
  for (const action of model.actions) {
    lines.push(`  ${action.number} ${action.notation} cost=${action.cost} pre=${numberList(action.preFacts)} ` +
      `neg=${numberList(action.negFacts)} add=${numberList(action.addFacts)} del=${numberList(action.delFacts)}`);
  }
  return lines;
}

function transform(model:GroundedModel):TransformResult {
  let negative = 0n;
  for (const action of model.actions) negative |= action.neg;
  const complements = new Map<number,number>(search.numbers(negative).map((fact, index) => [fact, model.facts.length + index]));
  const complement = (facts:bigint):bigint => {
    let result = 0n;
    for (const fact of search.numbers(facts)) if (complements.has(fact)) result |= search.bit(complements.get(fact)!);
    return result;
  };
  const actions:TransformAction[] = model.actions.map(action => ({number: action.number, original: action,
    pre: action.pre | complement(action.neg), add: action.add | complement(action.del),
    del: action.del | complement(action.add)}));
  return {actions, initial: model.initial | complement(negative & ~model.initial),
    count: complements.size, factCount: model.facts.length + complements.size};
}

function interfere(first:GroundedAction,second:GroundedAction):boolean {
  return (first.del & (second.pre | second.add)) !== 0n || (second.del & (first.pre | first.add)) !== 0n ||
    (first.add & second.neg) !== 0n || (second.add & first.neg) !== 0n;
}

function parallelize(plan:GroundedAction[]):GroundedAction[][] {
  const assigned:number[] = [];
  const layers:GroundedAction[][] = [];
  for (let index = 0; index < plan.length; index++) {
    let layer = 1;
    const action = plan[index];
    for (let before = 0; before < index; before++) {
      const earlier = plan[before];
      if ((earlier.add & action.pre) !== 0n || (earlier.del & action.neg) !== 0n || interfere(earlier, action)) {
        layer = Math.max(layer, assigned[before] + 1);
      }
    }
    assigned.push(layer);
    while (layers.length < layer) layers.push([]);
    layers[layer - 1].push(action);
  }
  return layers;
}

function validateParallel(model:GroundedModel,layers:GroundedAction[][]):string {
  let state = model.initial;
  for (let index = 0; index < layers.length; index++) {
    const layer = layers[index];
    if (layer.some(action => !search.applicable(state, action))) return `invalid at layer ${index + 1}`;
    for (let first = 0; first < layer.length; first++) {
      for (let second = first + 1; second < layer.length; second++) {
        if (interfere(layer[first], layer[second])) return `invalid at layer ${index + 1}`;
      }
    }
    let add = 0n;
    let del = 0n;
    for (const action of layer) {
      add |= action.add;
      del |= action.del;
    }
    state = (state & ~del) | add;
  }
  return search.contains(state, model.goal) ? 'valid' : 'goal not reached';
}

function improve(model:GroundedModel,original:GroundedAction[]):GroundedAction[] {
  let plan = original.slice();
  let index = 0;
  while (index < plan.length) {
    let state = model.initial;
    const retained = plan.slice(0, index);
    for (const action of retained) state = search.apply(state, action);
    for (const action of plan.slice(index + 1)) {
      if (search.applicable(state, action)) {
        state = search.apply(state, action);
        retained.push(action);
      }
    }
    if (search.contains(state, model.goal)) plan = retained;
    else index++;
  }
  return plan;
}

function validateSteps(domain:Domain,problem:Problem,steps:Step[]):Validation {
  const state = new Set<string>(problem.init.map(parser.notation));
  let cost = 0;
  for (let index = 0; index < steps.length; index++) {
    const step = steps[index];
    const prefix = `step ${index + 1} ${stepText(step)}:`;
    const action = domain.actionTable.get(step.name);
    let error:string|null = null;
    if (action === undefined) error = `unknown action ${step.name}`;
    else error = argumentError(domain, step.arguments, action.parameters.map(parameter => parameter.type), problem.objectTypes, 'object');
    let assignment:Map<string,string>;
    if (error === null) {
      assignment = new Map<string,string>(action!.parameters.map((parameter, number) => [parameter.name, step.arguments[number]]));
      for (const literal of action!.conditions) {
        const atom = grounding.substitute(literal.atom, assignment);
        const notation = parser.notation(atom);
        const truth = atom.predicate === '=' ? atom.terms[0] === atom.terms[1] : state.has(notation);
        if (truth === literal.negative) {
          error = `precondition ${literal.negative ? `(not ${notation})` : notation} is false`;
          break;
        }
      }
    }
    if (error !== null) return {result: 'invalid', messages: [`${prefix} ${error}`], correct: index, cost};
    for (const atom of action!.deletes) state.delete(parser.notation(grounding.substitute(atom, assignment)));
    for (const atom of action!.adds) state.add(parser.notation(grounding.substitute(atom, assignment)));
    cost += action.cost;
  }
  const missing = problem.goals.filter(atom => !state.has(parser.notation(atom)));
  return missing.length === 0 ? {result: 'valid', messages: [`length=${steps.length} cost=${cost}`], correct: steps.length, cost} :
    {result: 'goal not reached', messages: missing.map(atom => `unsatisfied goal ${parser.notation(atom)}`), correct: steps.length, cost};
}

function verdict(validation:Validation):string {
  return validation.result === 'valid' ? `valid ${validation.messages[0]}` : `${validation.result}: ${validation.messages[0]}`;
}

function analyzePlan(domain:Domain,problem:Problem,plan:GroundedAction[]):PlanAnalysis {
  const model = problem.model;
  const layers = parallelize(plan);
  const improved = improve(model, plan);
  let state = model.initial;
  let visited = 0n;
  for (const action of plan) {
    state = search.apply(state, action);
    visited |= state;
  }
  const landmarks = problem.engine.landmarks(model.initial).facts;
  const missed = landmarks.filter(fact => (visited & search.bit(fact)) === 0n);
  return {layers, improved, landmarks, missed, parallel: validateParallel(model, layers),
    validation: validateSteps(domain, problem, plan.map(stepOf)),
    improvedValidation: validateSteps(domain, problem, improved.map(stepOf))};
}

function prepareProblem(domain:Domain,problem:Problem,settings:Settings):void {
  validateProblem(domain, problem);
  problem.model = grounding.ground(domain, problem);
  problem.unreachable = problem.model.unreachable.length > 0;
  problem.results = [];
  if (!problem.unreachable) problem.engine = new heuristics.Engine(problem.model);
  for (const configuration of settings.runs) {
    const result = problem.unreachable ? {result: 'unreachable goal', plan: null, expanded: 0, generated: 0} :
      search.run(problem.model, problem.model.initial, configuration.algorithm, configuration.heuristic, settings, problem.engine);
    problem.results.push({...configuration, ...result});
  }
  if (problem.unreachable) problem.graph = {result:'unreachable goal',plan:null,expanded:0,generated:0,logs:[],memoHits:0,layers:null};
  else {
    const transformed = transform(problem.model);
    problem.graph = graphplan.solve(transformed.actions, transformed.factCount, transformed.initial, problem.model.goal, settings.graphplan);
    problem.graph.complements = transformed.count;
  }
  problem.results.push({...problem.graph, algorithm: 'graphplan', heuristic: 'none', tag: 'graphplan'});
  for (const result of problem.results) {
    if (result.result === 'solved') {
      result.cost = planCost(result.plan!);
      result.analysis = analyzePlan(domain, problem, result.plan!);
    }
  }
  const solved = problem.results.filter(result => result.result === 'solved');
  problem.solved = solved.length;
  problem.best = null;
  for (const result of solved) if (problem.best === null || result.cost! < problem.best) problem.best = result.cost!;
  problem.proof = problem.results.find(result => result.result === 'solved' && ['ucs none', 'astar hmax'].includes(result.tag)) || null;
  problem.optimal = problem.proof !== null ? problem.proof.cost! :
    problem.results.some(result => ['unreachable goal', 'dead end', 'exhausted', 'unreachable'].includes(result.result)) ? 'none' : 'unknown';
}

function heuristicText(values:Record<string,number>):string {
  return heuristics.names.map(name => `${name}=${valueText(values[name])}`).join(' ');
}

function planBlock(domain:Domain,problem:Problem,result:PlanResult,earlier:Map<string,string>):string[] {
  const plan = result.plan!, analysis = result.analysis!;
  const key = plan.map(action => action.number).join(',');
  let heading = `plan: length=${plan.length} cost=${result.cost}`;
  if (earlier.has(key)) heading += ` (same as ${earlier.get(key)})`;
  else earlier.set(key, result.tag);
  const lines = [heading];
  for (let index = 0; index < plan.length; index++) lines.push(`  ${index + 1} ${plan[index].notation}`);
  const schemas = [];
  for (const source of domain.actions) {
    const count = plan.filter(action => action.source === source).length;
    if (count > 0) schemas.push(`${source.name}=${count}`);
  }
  lines.push(list('schemas:', schemas));
  lines.push(`parallel: layers=${analysis.layers.length}`);
  for (let index = 0; index < analysis.layers.length; index++) lines.push(list(`  ${index + 1}:`, analysis.layers[index].map(action => action.notation)));
  const removed = plan.length - analysis.improved.length;
  lines.push(`improved: length=${analysis.improved.length} cost=${planCost(analysis.improved)} removed=${removed}`);
  if (removed > 0) {
    for (let index = 0; index < analysis.improved.length; index++) lines.push(`  ${index + 1} ${analysis.improved[index].notation}`);
  }
  lines.push(`landmarks reached: ${analysis.landmarks.length - analysis.missed.length}/${analysis.landmarks.length}`);
  for (const fact of analysis.missed) lines.push(`  missed ${problem.model.facts[fact].notation}`);
  return lines;
}

function profileLines(problem:Problem):string[] {
  const proof = problem.proof!;
  const model = problem.model;
  const lines = [`-- profile (${proof.tag}) --`];
  const overestimates = Object.fromEntries(heuristics.names.map(name => [name, 0]));
  let state = model.initial;
  let remaining = proof.cost!;
  for (let index = 0; index <= proof.plan!.length; index++) {
    const values = problem.engine.all(state);
    lines.push(`  ${index}: h*=${remaining} ${heuristicText(values)}`);
    for (const name of heuristics.names) if (values[name] > remaining) overestimates[name]++;
    if (index < proof.plan!.length) {
      state = search.apply(state, proof.plan![index]);
      remaining -= proof.plan![index].cost;
    }
  }
  lines.push(`overestimates: ${heuristicText(overestimates)}`);
  lines.push(`-- causal links (${proof.tag}) --`);
  const suppliers = Array(model.facts.length).fill(0);
  for (let index = 0; index < proof.plan!.length; index++) {
    const action = proof.plan![index];
    lines.push(list(`  ${index + 1} ${action.notation}:`, action.preFacts.map(fact => `${model.facts[fact].notation}<-${suppliers[fact]}`)));
    for (const fact of action.addFacts) suppliers[fact] = index + 1;
  }
  lines.push(list('  goal:', model.goalFacts.map(fact => `${model.facts[fact].notation}<-${suppliers[fact]}`)));
  return lines;
}

function plansLines(domain:Domain,problem:Problem):string[] {
  const lines = [`== problem ${problem.name} ==`];
  if (problem.unreachable) lines.push('initial h: unreachable goal');
  else {
    const initial = problem.model.initial;
    const values = problem.engine.all(initial);
    const landmarks = problem.engine.landmarks(initial);
    const relaxed = problem.engine.relaxedPlan(initial);
    lines.push(`initial h: ${heuristicText(values)}`);
    lines.push(`landmarks: ${landmarks.facts.length}`);
    for (const fact of landmarks.facts) lines.push(`  ${problem.model.facts[fact].notation}`);
    lines.push(`relaxed plan: length=${relaxed.plan.length} cost=${valueText(relaxed.value)}`);
    for (const action of relaxed.plan) lines.push(`  ${action.notation}`);
    lines.push(list('helpful:', relaxed.helpful.map(action => action.notation)));
  }
  const earlier = new Map<string,string>();
  for (const result of problem.results) {
    lines.push(`-- ${result.tag} --`);
    if (problem.unreachable) lines.push('result: FAIL (unreachable goal)');
    else {
      const text = result.result === 'solved' ? 'solved' : `FAIL (${result.result})`;
      lines.push(`result: ${text} expanded=${result.expanded} generated=${result.generated}`);
    }
    if (result.result === 'solved') append(lines, planBlock(domain, problem, result, earlier));
  }
  if (problem.proof !== null) append(lines, profileLines(problem));
  lines.push('');
  return lines;
}

function graphLines(problem:Problem):string[] {
  const lines = [`== problem ${problem.name} ==`];
  const result = problem.graph;
  if (problem.unreachable) lines.push('result: FAIL (unreachable goal)');
  else {
    lines.push(`complementary facts: ${result.complements}`);
    append(lines, result.logs);
    const counts = `searched=${result.expanded} memo_hits=${result.memoHits} tried=${result.generated}`;
    if (result.result === 'solved') {
      lines.push(`result: solved levels=${result.layers!.length} length=${result.plan!.length} cost=${planCost(result.plan!)} ${counts}`);
      for (let index = 0; index < result.layers!.length; index++) lines.push(list(`layer ${index + 1}:`, result.layers![index].map(action => action.notation)));
    } else lines.push(`result: FAIL (${result.result}) ${counts}`);
  }
  lines.push('');
  return lines;
}

function summaryLines(problems:Problem[],settings:Settings):string[] {
  const lines = ['== summary =='];
  for (const problem of problems) {
    lines.push(`${problem.name}: solved=${problem.solved}/${settings.runs.length + 1} ` +
      `best=${problem.best === null ? '-' : problem.best} optimal=${problem.optimal}`);
  }
  const tags = settings.runs.map(configuration => configuration.tag).concat('graphplan');
  for (let index = 0; index < tags.length; index++) {
    let solved = 0;
    let best = 0;
    let expanded = 0;
    let generated = 0;
    for (const problem of problems) {
      const result = problem.results[index];
      if (result.result === 'solved') {
        solved++;
        if (result.cost === problem.best) best++;
      }
      expanded += result.expanded;
      generated += result.generated;
    }
    lines.push(`${tags[index]}: solved=${solved} best=${best} expanded=${expanded} generated=${generated}`);
  }
  return lines;
}

function candidateLines(domain:Domain,problems:Problem[],candidates:CandidatePlan[],settings:Settings):{lines:string[];valid:number} {
  const byName = new Map<string,Problem>(problems.map(problem => [problem.name, problem]));
  const lines:string[] = ['== candidates =='];
  let valid = 0;
  for (const candidate of candidates) {
    const problem = byName.get(candidate.problem)!;
    const model = problem.model;
    const validation = validateSteps(domain, problem, candidate.steps);
    const prefix = `candidate ${candidate.number} ${problem.name} ${candidate.label}:`;
    if (validation.result === 'valid') {
      valid++;
      lines.push(`${prefix} ${verdict(validation)}`);
      const mapped = candidate.steps.map(step => model.actionTable.get(stepText(step))!);
      const improved = improve(model, mapped);
      lines.push(`  improved: length=${improved.length} cost=${planCost(improved)} removed=${mapped.length - improved.length} ` +
        `best known=${problem.best === null ? '-' : problem.best}`);
      continue;
    }
    lines.push(`${prefix} ${validation.result}`);
    for (const message of validation.messages) lines.push(`  ${message}`);
    if (problem.unreachable) {
      lines.push('  repair: FAIL (unreachable goal)');
      continue;
    }
    const prefixPlan = candidate.steps.slice(0, validation.correct).map(step => model.actionTable.get(stepText(step))!);
    let state = model.initial;
    for (const action of prefixPlan) state = search.apply(state, action);
    const repair = search.run(model, state, settings.repair.algorithm, settings.repair.heuristic, settings, problem.engine);
    if (repair.result !== 'solved') lines.push(`  repair: FAIL (${repair.result})`);
    else {
      const repaired = prefixPlan.concat(repair.plan);
      lines.push(`  repair: kept=${prefixPlan.length} added=${repair.plan.length} ${verdict(validateSteps(domain, problem, repaired.map(stepOf)))}`);
      for (let index = 0; index < repaired.length; index++) lines.push(`    ${index + 1} ${repaired[index].notation}`);
    }
  }
  return {lines, valid};
}

function writeOutputs(domain:Domain,problems:Problem[],settings:Settings,candidates:CandidatePlan[]):void {
  const ground = domainLines(domain);
  const plans = [];
  const graph = [];
  const validation = [];
  const comparison = ['problem,algorithm,heuristic,length,cost,expanded,generated'];
  let validatedPlans = 0;
  let validPlans = 0;
  for (const problem of problems) {
    ground.push('');
    append(ground, groundingLines(domain, problem));
    append(plans, plansLines(domain, problem));
    append(graph, graphLines(problem));
    validation.push(`== problem ${problem.name} ==`);
    for (const result of problem.results) {
      if (result.result === 'solved') {
        validatedPlans++;
        if (result.analysis!.validation.result === 'valid') validPlans++;
        validation.push(`${result.tag}: ${verdict(result.analysis!.validation)}`,
          `  parallel: ${result.analysis!.parallel}`, `  improved: ${verdict(result.analysis!.improvedValidation)}`);
      }
      comparison.push([problem.name, result.algorithm, result.heuristic, result.plan === null ? '-' : result.plan!.length,
        result.plan === null ? '-' : result.cost, result.expanded, result.generated].join(','));
    }
    validation.push('');
  }
  append(plans, summaryLines(problems, settings));
  const checkedCandidates = candidateLines(domain, problems, candidates, settings);
  append(validation, checkedCandidates.lines);
  validation.push('', '== summary ==', `plans: ${validatedPlans} valid: ${validPlans}`,
    `candidates: ${candidates.length} valid: ${checkedCandidates.valid}`);
  mkdirSync('output', {recursive: true});
  const files = {'grounding.txt': ground, 'plans.txt': plans, 'graphplan.txt': graph, 'validation.txt': validation, 'comparison.csv': comparison};
  for (const [name, lines] of Object.entries(files)) writeFileSync(`output/${name}`, lines.join('\n') + '\n', 'ascii');
}

function main():void {
  const domain = parser.domain(parser.readText('domain.txt'));
  const problems = parser.problems(parser.readText('problems.txt'));
  const settings = readSettings(parser.readText('params.txt'));
  const candidates = readCandidates(parser.readText('candidates.txt'));
  validateDomain(domain);
  for (const problem of problems) prepareProblem(domain, problem, settings);
  writeOutputs(domain, problems, settings, candidates);
}

main();

import {readFileSync} from 'node:fs';
import type {SExpr,TypedName,Atom,Literal,Domain,Problem,ActionSchema} from './types.ts';

export function readText(name:string):string {
  return readFileSync(`input/${name}`, 'ascii');
}

export function expressions(text:string):SExpr[] {
  const tokens = text.replace(/;[^\n]*/g, '').match(/[()]|[^ ()\n]+/g) || [];
  let position = 0;
  function expression():SExpr {
    const token = tokens[position++];
    if (token !== '(') return token;
    const result:SExpr[] = [];
    while (tokens[position] !== ')') result.push(expression());
    position++;
    return result;
  }
  const result:SExpr[] = [];
  while (position < tokens.length) result.push(expression());
  return result;
}

export function typedList(words:string[]):TypedName[] {
  const result:TypedName[] = [];
  let pending:string[] = [];
  for (let index = 0; index < words.length; index++) {
    if (words[index] === '-') {
      const type = words[++index];
      for (const name of pending) result.push({name, type});
      pending = [];
    } else pending.push(words[index]);
  }
  for (const name of pending) result.push({name, type: 'object'});
  return result;
}

export function atom(expression:SExpr[]):Atom {
  return {predicate: expression[0] as string, terms: expression.slice(1) as string[]};
}

export function notation(value:Atom):string {
  return `(${[value.predicate, ...value.terms].join(' ')})`;
}

export function literal(expression:SExpr[]):Literal {
  return expression[0] === 'not' && Array.isArray(expression[1]) ? {negative: true, atom: atom(expression[1] as SExpr[])} :
    {negative: false, atom: atom(expression)};
}

export function conjuncts(expression:SExpr[], allowEmpty = true):SExpr[][] {
  const conjunction = expression[0] === 'and' && (allowEmpty || expression.length > 1) &&
    expression.slice(1).every(item => Array.isArray(item));
  return conjunction ? expression.slice(1) as SExpr[][] : [expression];
}

export function domain(text:string):Domain {
  const expression = expressions(text)[0] as SExpr[];
  const result:Domain = {name:(expression[1] as SExpr[])[1] as string, types:['object'],
    parents:new Map<string,string|null>([['object',null]]),predicates:[],actions:[],
    predicateTable:new Map(),fluent:new Set(),static:new Set(),diagnostics:[],
    actionTable:new Map()};
  for (const section of expression.slice(2) as SExpr[][]) {
    if (section[0] === ':types') {
      for (const word of section.slice(1)) {
        if (word !== '-' && !result.parents.has(word as string)) {
          result.types.push(word as string);
          result.parents.set(word as string, 'object');
        }
      }
      for (const item of typedList(section.slice(1) as string[])) result.parents.set(item.name, item.type);
    } else if (section[0] === ':predicates') {
      for (const declaration of section.slice(1) as SExpr[][]) {
        result.predicates.push({name: declaration[0] as string, types: typedList(declaration.slice(1) as string[]).map(item => item.type),
          number: result.predicates.length});
      }
    } else if (section[0] === ':action') {
      const fields = new Map<string,SExpr[]>();
      for (let index = 2; index < section.length; index += 2) fields.set(section[index] as string, section[index + 1] as SExpr[]);
      const action:ActionSchema = {name: section[1] as string,parameters:typedList(fields.get(':parameters') as string[]), conditions:[],effects:[],cost:1,adds:[],deletes:[]};
      if (fields.has(':precondition')) action.conditions = conjuncts(fields.get(':precondition')!).map(literal);
      for (const element of conjuncts(fields.get(':effect')!, false)) {
        if (element[0] === 'increase' && Array.isArray(element[1])) action.cost = Number(element[2]);
        else action.effects.push(literal(element));
      }
      action.adds = action.effects.filter(item => !item.negative).map(item => item.atom);
      action.deletes = action.effects.filter(item => item.negative).map(item => item.atom);
      result.actions.push(action);
    }
  }
  result.predicateTable = new Map(result.predicates.map(predicate => [predicate.name, predicate]));
  return result;
}

export function problems(text:string):Problem[] {
  return expressions(text).map(value => {
    const expression = value as SExpr[];
    const sections = new Map<string,SExpr[]>( (expression.slice(2) as SExpr[][]).map(section => [section[0] as string, section.slice(1)]));
    const objects = typedList(sections.get(':objects') as string[]).map((item, number) => ({...item, number}));
    return {name: (expression[1] as SExpr[])[1] as string, objects, objectTypes: new Map(objects.map(item => [item.name, item.type])),
      objectNumbers: new Map(objects.map(item => [item.name, item.number])),
      init: (sections.get(':init') as SExpr[][]).map(atom), goals: conjuncts(sections.get(':goal')![0] as SExpr[], false).map(atom)} as Problem;
  });
}

import type {GroundedModel,GroundedAction,Settings,SearchNode,SearchResult} from './types.ts';
import type {Engine} from './heuristics.ts';

export function bit(number:number):bigint {
  return 1n << BigInt(number);
}

export function mask(numbers:Iterable<number>):bigint {
  let result = 0n;
  for (const number of numbers) result |= bit(number);
  return result;
}

export function numbers(value:bigint):number[] {
  const result:number[] = [];
  for (let number = 0; value !== 0n; number++, value >>= 1n) if ((value & 1n) !== 0n) result.push(number);
  return result;
}

export function contains(state:bigint,facts:bigint):boolean {
  return (state & facts) === facts;
}

export function applicable(state:bigint,action:GroundedAction):boolean {
  return contains(state, action.pre) && (state & action.neg) === 0n;
}

export function apply(state:bigint,action:GroundedAction):bigint {
  return (state & ~action.del) | action.add;
}

class Heap {
  items:SearchNode[];
  constructor() {
    this.items = [];
  }

  compare(a:SearchNode,b:SearchNode):number {
    return a.f - b.f || a.h - b.h || a.serial - b.serial;
  }

  push(value:SearchNode):void {
    let index = this.items.length;
    this.items.push(value);
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (this.compare(this.items[parent], value) <= 0) break;
      this.items[index] = this.items[parent];
      index = parent;
    }
    this.items[index] = value;
  }

  pop():SearchNode {
    const first = this.items[0];
    const last = this.items.pop()!;
    if (this.items.length === 0) return first;
    let index = 0;
    while (index * 2 + 1 < this.items.length) {
      let child = index * 2 + 1;
      if (child + 1 < this.items.length && this.compare(this.items[child + 1], this.items[child]) < 0) child++;
      if (this.compare(last, this.items[child]) <= 0) break;
      this.items[index] = this.items[child];
      index = child;
    }
    this.items[index] = last;
    return first;
  }
}

function bestFirst(problem:GroundedModel,start:bigint,algorithm:string,heuristic:string,settings:Settings,engine:Engine):SearchResult {
  let expanded = 0;
  let generated = 0;
  const finish = (result:string,plan:GroundedAction[]|null = null):SearchResult => ({result, plan, expanded, generated});
  const initialH = engine.value(start, heuristic);
  if (initialH === Infinity) return finish('dead end');
  const priority = (g:number,d:number,h:number):number => algorithm === 'bfs' ? d : algorithm === 'ucs' ? g : algorithm === 'gbfs' ? h :
    g + (algorithm === 'wastar' ? settings.weight : 1) * h;
  const best = new Map<bigint,number>([[start,0]]);
  const open = new Heap();
  let serial = 0;
  open.push({state: start, g: 0, d: 0, h: initialH, f: priority(0, 0, initialH), serial: serial++, parent: null, action: null});
  const revisits = ['ucs', 'astar', 'wastar'].includes(algorithm);
  while (open.items.length > 0) {
    const node = open.pop();
    if (revisits && node.g > best.get(node.state)!) continue;
    if (contains(node.state, problem.goal)) {
      const plan:GroundedAction[] = [];
      for (let current:SearchNode = node; current.parent !== null; current = current.parent) plan.push(current.action!);
      return finish('solved', plan.reverse());
    }
    if (expanded === settings.budget) return finish('budget');
    expanded++;
    for (const action of problem.actions) {
      if (!applicable(node.state, action)) continue;
      generated++;
      const state = apply(node.state, action);
      const g = node.g + action.cost;
      if (best.has(state) && (!revisits || best.get(state) <= g)) continue;
      best.set(state, g);
      const h = engine.value(state, heuristic);
      if (h === Infinity) continue;
      const d = node.d + 1;
      open.push({state, g, d, h, f: priority(g, d, h), serial: serial++, parent: node, action});
    }
  }
  return finish('exhausted');
}

function hillClimb(problem:GroundedModel,start:bigint,heuristic:string,settings:Settings,engine:Engine):SearchResult {
  let expanded = 0;
  let generated = 0;
  let plan:GroundedAction[] = [];
  let current = start;
  let currentH = engine.value(start, heuristic);
  const finish = (result:string):SearchResult => ({result, plan: result === 'solved' ? plan : null, expanded, generated});
  if (currentH === Infinity) return finish('dead end');
  climbing: while (true) {
    if (contains(current, problem.goal)) return finish('solved');
    const queue:{state:bigint;path:GroundedAction[]}[] = [{state:current,path:[]}];
    const visited = new Set<bigint>([current]);
    for (let index = 0; index < queue.length; index++) {
      const node = queue[index];
      if (expanded === settings.budget) return finish('budget');
      expanded++;
      for (const action of engine.relaxedPlan(node.state).helpful) {
        const state = apply(node.state, action);
        generated++;
        if (visited.has(state)) continue;
        visited.add(state);
        const h = engine.value(state, heuristic);
        if (h === Infinity) continue;
        const path = node.path.concat(action);
        if (h < currentH) {
          plan = plan.concat(path);
          current = state;
          currentH = h;
          continue climbing;
        }
        queue.push({state, path});
      }
    }
    return finish('stuck');
  }
}

export function run(problem:GroundedModel,start:bigint,algorithm:string,heuristic:string,settings:Settings,engine:Engine):SearchResult {
  return algorithm === 'ehc' ? hillClimb(problem, start, heuristic, settings, engine) :
    bestFirst(problem, start, algorithm, heuristic, settings, engine);
}

